window.HUB_CATALOG=[{"id":1,"categoryId":1,"title":"Visión del servidor","summary":"Una experiencia de rol ambientada en la época clásica de Naruto.","body":"El proyecto plantea un sandbox de rol de escala mediana, con personajes originales de los jugadores. Los personajes canon se reservan para NPC.\n\nEl escenario comprende Konoha y parte del País del Fuego. Incluye Academia, hospital, edificio del Hokage, distrito comercial, viviendas, distrito Uchiha, zonas de entrenamiento, puertas y ocio. En el exterior: bosques, caminos, puentes, asentamientos y puestos fronterizos. Cada zona debe tener una utilidad real.\n\nZenkai, Tenkai y Tekurai son referencias de inspiración, con identidad propia. Se quieren evitar mapas vacíos, mala administración, escasas oportunidades de desarrollo, combate desequilibrado y limitaciones narrativas excesivas.","example":"","questions":["¿Qué información del mundo necesita el equipo para revisar las mecánicas?"],"type":"defined","reference":true,"source":"VISIÓN GENERAL","designNote":"","key":"legacy-1","category":"Personajes y clanes"},{"id":2,"categoryId":1,"title":"Clanes disponibles","summary":"La selección inicial incluye nueve clanes y la opción de jugar sin clan.","body":"Los clanes confirmados son Uchiha, Hyūga, Senju, Nara, Akimichi, Yamanaka, Aburame, Inuzuka y Sarutobi.\n\nTambién se puede crear un personaje sin clan. Uzumaki no estará disponible al inicio.","example":"","questions":["¿Se entiende con claridad la selección inicial?","¿Qué información de cada clan hace falta documentar sin cambiar esta selección?"],"type":"defined","reference":false,"source":"CLANES (confirmado)","designNote":"","key":"legacy-2","category":"Personajes y clanes"},{"id":3,"categoryId":1,"title":"Acceso a los clanes","summary":"Pertenecer a un clan requiere solicitud y aprobación.","body":"El acceso no se obtiene automáticamente. El jugador presenta una solicitud y esta debe aprobarse.\n\nEl maestro no concreta el formulario, los criterios ni el procedimiento de aprobación. Esos detalles siguen abiertos.","example":"Ilustrativo: una solicitud podría describir el vínculo del personaje con el clan. No es un requisito aprobado.","questions":["¿Qué debería explicar una solicitud?","¿Qué criterios y procedimiento convendría proponer?"],"type":"defined","reference":false,"source":"CLANES (confirmado)","designNote":"","key":"legacy-3","category":"Personajes y clanes"},{"id":4,"categoryId":1,"title":"Bonificaciones de clan","summary":"Ventajas pequeñas que se añaden a las estadísticas personales.","body":"Las bonificaciones de clan se suman a las estadísticas del personaje y no consumen su límite natural de 100.\n\nLos valores concretos están pendientes de equilibrio.","example":"Ejemplo ilustrativo del maestro: 100 en Katon más una bonificación de 2 daría 102. Ese +2 no es un valor definitivo.","questions":["¿Qué valores convendría estudiar para cada clan?","¿Cómo comprobar que las diferencias sigan siendo pequeñas?"],"type":"defined","reference":false,"source":"CLANES (confirmado)","designNote":"","key":"legacy-4","category":"Personajes y clanes"},{"id":5,"categoryId":8,"title":"Dōjutsus como habilidades de clan","summary":"Sharingan y Byakugan son habilidades, no estadísticas.","body":"Sharingan y Byakugan son habilidades de clan, no estadísticas personales.\n\nEl documento maestro todavía no concreta sus reglas oculares. En fase 3 el usuario ha aportado el diseño previo del Sharingan, que se presenta en sus seis fichas específicas pendiente de revisión por el equipo.\n\nEl funcionamiento concreto del Byakugan sigue pendiente de definir. No se añaden otras capacidades oculares.","example":"","questions":["¿Qué reglas deben diseñarse por separado para cada habilidad ocular?"],"type":"defined","reference":false,"source":"CLANES (confirmado)","designNote":"","key":"legacy-5","category":"Dōjutsus"},{"id":6,"categoryId":2,"title":"Progresión individual de estadísticas","summary":"Cada atributo tiene su propia experiencia y un límite natural de 100.","body":"Cada estadística progresa con su propia experiencia. No existe una bolsa común de puntos para repartir.\n\nEl límite natural es 100. Las pequeñas bonificaciones de clan se añaden por separado.","example":"","questions":["¿Qué actividades deberían aportar experiencia a cada atributo?","¿Qué ritmo de avance convendría probar sin fijar aún valores?"],"type":"defined","reference":false,"source":"ESTADÍSTICAS (confirmado)","designNote":"","key":"legacy-6","category":"Estadísticas"},{"id":7,"categoryId":2,"title":"Estadísticas físicas","summary":"Consulta los atributos confirmados de este grupo.","body":"Constitución, Taijutsu, Bukijutsu, Velocidad y Salto.\n\nEsta ficha es una referencia de organización; no añade fórmulas ni efectos que el maestro no haya definido.","example":"","questions":["¿Qué definiciones requieren una ficha específica o una aclaración?"],"type":"defined","reference":true,"source":"ESTADÍSTICAS (confirmado)","designNote":"","key":"legacy-7","category":"Estadísticas"},{"id":8,"categoryId":2,"title":"Naturalezas como estadísticas","summary":"Consulta los atributos confirmados de este grupo.","body":"Katon, Fūton, Raiton, Doton, Suiton, Yin y Yang.\n\nEsta ficha es una referencia de organización; no añade fórmulas ni efectos que el maestro no haya definido.","example":"","questions":["¿Qué definiciones requieren una ficha específica o una aclaración?"],"type":"defined","reference":true,"source":"ESTADÍSTICAS (confirmado)","designNote":"","key":"legacy-8","category":"Estadísticas"},{"id":9,"categoryId":2,"title":"Estadísticas técnicas","summary":"Consulta los atributos confirmados de este grupo.","body":"Ninjutsu, Genjutsu, Control de Chakra, Sellos y Medicina Ninja.\n\nEsta ficha es una referencia de organización; no añade fórmulas ni efectos que el maestro no haya definido.","example":"","questions":["¿Qué definiciones requieren una ficha específica o una aclaración?"],"type":"defined","reference":true,"source":"ESTADÍSTICAS (confirmado)","designNote":"","key":"legacy-9","category":"Estadísticas"},{"id":10,"categoryId":2,"title":"Estadísticas mentales y de recuperación","summary":"Consulta los atributos confirmados de este grupo.","body":"Espíritu, Percepción, Recuperación, Regeneración de Chakra y Regeneración de Vida.\n\nEsta ficha es una referencia de organización; no añade fórmulas ni efectos que el maestro no haya definido.","example":"","questions":["¿Qué definiciones requieren una ficha específica o una aclaración?"],"type":"defined","reference":true,"source":"ESTADÍSTICAS (confirmado)","designNote":"","key":"legacy-10","category":"Estadísticas"},{"id":11,"categoryId":2,"title":"Guía de definiciones de atributos","summary":"Referencia de los significados confirmados y sus límites.","body":"Constitución determina la vida máxima y Espíritu el chakra máximo. Recuperación describe el tiempo de recuperación; Regeneración de Vida y de Chakra describen la cantidad regenerada.\n\nNinjutsu representa poder y variedad de técnicas. Control de Chakra representa eficiencia y precisión. Genjutsu permite lanzar y resistir ilusiones; Yin es requisito de las avanzadas.\n\nYin y Yang son estadísticas individuales y no pueden ser afinidad principal. Yin se asocia a energía espiritual e imaginación; Yang a energía física y vitalidad. Percepción está ligada parcialmente a Genjutsu.\n\nConvertir Recuperación en espera previa a regenerar y repartir detectar, lanzar y deshacer ilusiones siguen siendo propuestas. Las fichas específicas permiten debatir cada cuestión por separado.","example":"","questions":["¿Qué definiciones necesitan ejemplos o aclaraciones?"],"type":"defined","reference":true,"source":"ESTADÍSTICAS (confirmado)","designNote":"","key":"legacy-11","category":"Estadísticas"},{"id":12,"categoryId":2,"title":"Bukijutsu como disciplina","summary":"Se mantiene Bukijutsu en la lista de estadísticas.","body":"La disciplina confirmada es Bukijutsu. No se sustituye por Kenjutsu.\n\nEsta decisión no concede acceso general a katanas: su disponibilidad tiene reglas propias.","example":"","questions":["¿Qué prácticas y técnicas deberían desarrollar Bukijutsu dentro de las armas disponibles?"],"type":"defined","reference":false,"source":"ESTADÍSTICAS (confirmado)","designNote":"","key":"legacy-12","category":"Estadísticas"},{"id":13,"categoryId":3,"title":"Rangos ninja","summary":"El recorrido pasa por Academia, Genin, Chūnin y Jōnin.","body":"Los rangos confirmados son Academia, Genin, Chūnin y Jōnin, además de posiciones especiales como ANBU y liderazgo.\n\nAscender depende del rol. La experiencia por sí sola no concede un rango.","example":"","questions":["¿Qué situaciones narrativas deberían mostrar la preparación para cada rango?"],"type":"defined","reference":false,"source":"PROGRESIÓN Y RANGOS (confirmado)","designNote":"","key":"legacy-13","category":"Progresión ninja"},{"id":14,"categoryId":3,"title":"Límites suaves por rango","summary":"El progreso se ralentiza al llegar al límite del rango.","body":"Al alcanzar el límite correspondiente al rango, avanzar resulta mucho más lento. No se pierde lo aprendido.\n\nAl ascender se recupera la velocidad de progresión. Los límites y multiplicadores concretos siguen pendientes.","example":"","questions":["¿Cómo comunicar la ralentización al jugador?","¿Qué límites y ritmos se deberían ensayar?"],"type":"defined","reference":false,"source":"PROGRESIÓN Y RANGOS (confirmado)","designNote":"","key":"legacy-14","category":"Progresión ninja"},{"id":15,"categoryId":3,"title":"Ascensos mediante rol","summary":"El rango se gana mediante desarrollo narrativo.","body":"Los ascensos se deciden en roleplay y no se conceden automáticamente por acumular experiencia.\n\nLa gestión inicial corresponde al staff; el sistema mixto previsto se explica por separado.","example":"","questions":["¿Qué evidencias narrativas deberían acompañar una propuesta de ascenso?"],"type":"defined","reference":false,"source":"PROGRESIÓN Y RANGOS (confirmado)","designNote":"","key":"legacy-15","category":"Progresión ninja"},{"id":16,"categoryId":3,"title":"Gestión de ascensos","summary":"El staff gestiona los ascensos al inicio; después se prevé un sistema mixto.","body":"Al comienzo, solo el staff decide los ascensos. El sistema previsto combina propuestas de autoridades del rol con aprobación del staff para rangos altos.\n\nTodos los ascensos deben quedar registrados. No se han fijado aquí nuevos requisitos ni plazos.","example":"","questions":["¿Cómo debería presentarse una propuesta de ascenso?","¿Qué información debe conservar su registro?"],"type":"defined","reference":false,"source":"PROGRESIÓN Y RANGOS (confirmado)","designNote":"","key":"legacy-16","category":"Progresión ninja"},{"id":17,"categoryId":5,"title":"Ventaja de la afinidad principal","summary":"La afinidad facilita aprender su naturaleza.","body":"Existen cinco naturalezas básicas. La afinidad principal aporta ventaja de aprendizaje, sin una ventaja exagerada de daño.\n\nNo se han fijado multiplicadores concretos de aprendizaje.","example":"","questions":["¿Cómo hacer visible la ventaja de aprendizaje?","¿Qué ritmo convendría probar manteniendo esta filosofía?"],"type":"defined","reference":false,"source":"AFINIDADES DE CHAKRA (confirmado, tema cerrado)","designNote":"","key":"legacy-17","category":"Afinidades de chakra"},{"id":18,"categoryId":5,"title":"Elección definitiva de afinidad","summary":"El jugador elige su afinidad al presentar la ficha de personaje.","body":"La afinidad principal la elige el jugador en la ficha que rellena para acceder al servidor. Esa elección es definitiva.\n\nYin y Yang no pueden elegirse como afinidad principal.","example":"","questions":["¿Qué explicación necesita el jugador antes de confirmar una elección definitiva?"],"type":"defined","reference":false,"source":"AFINIDADES DE CHAKRA (confirmado, tema cerrado)","designNote":"","key":"legacy-18","category":"Afinidades de chakra"},{"id":19,"categoryId":5,"title":"Variedad entre afinidades","summary":"Se diseñarán jutsus atractivos para las cinco afinidades.","body":"El objetivo confirmado es ofrecer técnicas llamativas para todas las afinidades. El catálogo concreto todavía debe diseñarse.\n\nEsta ficha explica una intención de diseño, no una lista aprobada de técnicas.","example":"","questions":["¿Qué necesidades debería cubrir el catálogo inicial?"],"type":"defined","reference":true,"source":"AFINIDADES DE CHAKRA (confirmado, tema cerrado)","designNote":"","key":"legacy-19","category":"Afinidades de chakra"},{"id":20,"categoryId":5,"title":"Aprendizaje de otras naturalezas","summary":"Se pueden aprender todas, con mayor limitación fuera de la afinidad principal.","body":"El conocimiento de naturalezas distintas de la principal será más limitado. Esto se resuelve mediante los niveles y límites por rango ya acordados, sin añadir otro mecanismo.\n\nAprender una segunda naturaleza tiene además requisitos propios.","example":"","questions":["¿Cómo explicar al jugador la diferencia de dominio entre naturalezas?"],"type":"defined","reference":false,"source":"AFINIDADES DE CHAKRA (confirmado, tema cerrado)","designNote":"","key":"legacy-20","category":"Afinidades de chakra"},{"id":21,"categoryId":5,"title":"Segunda naturaleza","summary":"Requiere al menos rango Chūnin y un maestro.","body":"Para empezar una segunda naturaleza se exige como mínimo Chūnin. El jugador debe elegir un maestro, del clan o alguien que tenga esa afinidad.\n\nLos NPC instructores son una propuesta separada, todavía sin confirmar.","example":"","questions":["¿Cómo organizar la enseñanza entre personajes?","¿Qué evidencia de aprendizaje debería documentarse?"],"type":"defined","reference":false,"source":"AFINIDADES DE CHAKRA (confirmado, tema cerrado)","designNote":"","key":"legacy-21","category":"Afinidades de chakra"},{"id":22,"categoryId":5,"title":"Técnicas de clan de otra naturaleza","summary":"Una afinidad distinta no bloquea para siempre las técnicas del clan.","body":"Se aprenden más adelante, cumpliendo un nivel mínimo en la naturaleza, un rango adecuado y maestro o prueba del clan.\n\nLos valores y pruebas concretos todavía no están definidos.","example":"Ejemplo del maestro: un Uchiha con afinidad Fūton podrá aprender técnicas Katon del clan más adelante; no se fija cuándo exactamente.","questions":["¿Cómo desarrollar criterios específicos para cada técnica?"],"type":"defined","reference":false,"source":"AFINIDADES DE CHAKRA (confirmado, tema cerrado)","designNote":"","key":"legacy-22","category":"Afinidades de chakra"},{"id":23,"categoryId":4,"title":"Entrenamiento sin abuso","summary":"Los rendimientos decrecientes limitan la repetición excesiva.","body":"El diseño prevé protección frente a repetición, macros y abuso de actividades simples mediante rendimientos decrecientes.\n\nNo se han aprobado fórmulas, umbrales ni herramientas técnicas concretas.","example":"","questions":["¿Qué patrones deberían considerarse repetición abusiva?","¿Cómo evitar perjudicar el entrenamiento legítimo?"],"type":"defined","reference":false,"source":"ENTRENAMIENTO (confirmado)","designNote":"","key":"legacy-23","category":"Entrenamiento"},{"id":24,"categoryId":4,"title":"Práctica ligada al atributo","summary":"La actividad debe trabajar realmente la estadística que mejora.","body":"Cada estadística se entrena mediante actividades relacionadas con ella. No se asignan aquí cantidades de experiencia ni actividades obligatorias adicionales.","example":"","questions":["¿Qué actividades encajan con cada atributo?","¿Cómo distinguir práctica útil de acciones repetidas sin contexto?"],"type":"defined","reference":false,"source":"ENTRENAMIENTO (confirmado)","designNote":"","key":"legacy-24","category":"Entrenamiento"},{"id":25,"categoryId":4,"title":"Entrenamiento acompañado","summary":"Un instructor o un compañero de sparring mejora el aprendizaje.","body":"Entrenar en solitario concede menos experiencia. Entrenar con instructor o en sparring con otro jugador concede bastante más.\n\nLa diferencia numérica aún debe equilibrarse.","example":"","questions":["¿Cómo fomentar el entrenamiento compartido?","¿Qué diferencia de experiencia sería razonable probar?"],"type":"defined","reference":false,"source":"ENTRENAMIENTO (confirmado)","designNote":"","key":"legacy-25","category":"Entrenamiento"},{"id":26,"categoryId":4,"title":"NPC de práctica","summary":"Los NPC permiten practicar cuando faltan jugadores.","body":"Pueden actuar como pacientes u oponentes de entrenamiento cuando no haya jugadores. Conceden bastante menos experiencia.\n\nEsto no confirma que existan NPC instructores de cada naturaleza ni verifica capacidades de nanos world.","example":"","questions":["¿Qué prácticas deberían poder mantenerse sin otros jugadores?"],"type":"defined","reference":false,"source":"ENTRENAMIENTO (confirmado)","designNote":"","key":"legacy-26","category":"Entrenamiento"},{"id":27,"categoryId":6,"title":"Rangos de los jutsus","summary":"Las técnicas se clasifican de E a S sin equivaler al rango del personaje.","body":"Los rangos de técnica son E, D, C, B, A y S. Su clasificación no determina directamente qué rango de personaje puede aprenderlos.\n\nSe deben cumplir los requisitos y la justificación narrativa de cada caso.","example":"Ejemplo confirmado del maestro: un Genin puede aprender un jutsu C si cumple requisitos y tiene justificación de rol. No es acceso automático a todos los C.","questions":["¿Cómo explicar los requisitos sin confundir rango ninja y rango de técnica?"],"type":"defined","reference":false,"source":"JUTSUS (confirmado)","designNote":"","key":"legacy-27","category":"Jutsus"},{"id":28,"categoryId":6,"title":"Ficha de cada jutsu","summary":"Cada técnica tendrá una descripción completa y comparable.","body":"La ficha incluye nombre, categoría, rango, naturaleza, requisitos de estadísticas, coste de chakra, tiempo de lanzamiento, enfriamiento, efecto y método de aprendizaje.\n\nTener estos campos no significa que ya estén definidos sus valores. La tabla base de requisitos sigue siendo una propuesta.","example":"","questions":["¿Los campos permiten entender y comparar una técnica?","¿Qué dudas debería resolver cada ficha?"],"type":"defined","reference":false,"source":"JUTSUS (confirmado)","designNote":"","key":"legacy-28","category":"Jutsus"},{"id":29,"categoryId":6,"title":"Aprendizaje de jutsus","summary":"Las técnicas básicas y las avanzadas tienen vías distintas.","body":"Las básicas se obtienen por progresión. Las avanzadas o especiales se aprenden con maestros, pergaminos, pruebas o requisitos.\n\nEl catálogo todavía debe concretar qué vía corresponde a cada técnica.","example":"","questions":["¿Qué método de aprendizaje encaja con cada tipo de técnica?"],"type":"defined","reference":false,"source":"JUTSUS (confirmado)","designNote":"","key":"legacy-29","category":"Jutsus"},{"id":30,"categoryId":7,"title":"Combate híbrido","summary":"Importan tanto la habilidad del jugador como el desarrollo del personaje.","body":"Reflejos, combos, esquivas, bloqueos y precisión influyen en el combate. También influyen estadísticas, entrenamiento y dominio de técnicas.\n\nLas estadísticas no garantizan la victoria. Los controles y la implementación final siguen pendientes de verificación técnica.","example":"","questions":["¿Cómo comprobar que ambos factores tengan peso?","¿Qué situaciones revelarían un desequilibrio?"],"type":"defined","reference":false,"source":"COMBATE (confirmado)","designNote":"","key":"legacy-30","category":"Combate"},{"id":31,"categoryId":7,"title":"Elección de estilo de combate","summary":"El jugador puede orientar su combate a armas, cuerpo a cuerpo o ninjutsu.","body":"Bukijutsu, Taijutsu y Ninjutsu deben resultar opciones viables sin desequilibrios exagerados.\n\nCada estilo tiene ventajas y límites definidos en sus fichas.","example":"","questions":["¿Qué pruebas permitirían comparar la viabilidad de los tres estilos?"],"type":"defined","reference":false,"source":"COMBATE (confirmado)","designNote":"","key":"legacy-31","category":"Combate"},{"id":32,"categoryId":7,"title":"Guía de estilos de combate","summary":"Referencia conjunta de las diferencias entre los tres estilos.","body":"Taijutsu: cercano, rápido, sin chakra y de poco alcance.\n\nBukijutsu: distancia y precisión, con poca munición o daño. El maestro no fija valores ni resuelve más ese límite.\n\nNinjutsu: más daño y variedad, con gasto de chakra, tiempo de lanzamiento y posibilidad de interrupción.\n\nLas tres fichas específicas permiten comparar cada estilo por separado.","example":"","questions":["¿La separación facilita comparar los estilos?"],"type":"defined","reference":true,"source":"COMBATE (confirmado)","designNote":"","key":"legacy-32","category":"Combate"},{"id":33,"categoryId":7,"title":"Acceso a las katanas","summary":"Las katanas estarán reservadas a personas contadas.","body":"Quién consigue una katana se decide en el rol. No existe una concesión automática por estadísticas.\n\nLa propuesta de un registro de katanas se debate por separado.","example":"","questions":["¿Qué situaciones narrativas podrían justificar el acceso sin fijarlas todavía como requisitos?"],"type":"defined","reference":false,"source":"COMBATE (confirmado)","designNote":"","key":"legacy-33","category":"Combate"},{"id":34,"categoryId":7,"title":"Inicio de regeneración en combate","summary":"Hay que pasar un tiempo sin recibir golpes antes de regenerar.","body":"La regeneración en combate comienza después de un periodo sin ser golpeado. El maestro no define su duración.\n\nQue Recuperación determine esa espera y que usar jutsus la reinicie son propuestas independientes.","example":"","questions":["¿Qué tiempos convendría probar?","¿Cómo comunicar que la regeneración todavía no ha empezado?"],"type":"defined","reference":false,"source":"COMBATE (confirmado)","designNote":"","key":"legacy-34","category":"Combate"},{"id":35,"categoryId":7,"title":"Regeneración activa de chakra","summary":"Se prevé una tecla del ratón para recuperar chakra durante el combate.","body":"La recuperación activa solo restaura chakra, no vida. El diseño prevé activarla con una tecla del ratón.\n\nEl uso de teclas extra en nanos world sigue sin verificarse. La exposición al canalizar y las interrupciones son propuestas, no reglas confirmadas.","example":"","questions":["¿Cómo debería comunicarse la canalización?","¿Qué controles deben verificarse antes de implementar?"],"type":"defined","reference":false,"source":"COMBATE (confirmado)","designNote":"","key":"legacy-35","category":"Combate"},{"id":36,"categoryId":11,"title":"Economía en ryō","summary":"El planteamiento económico usa ryō e incluye actividades de los jugadores.","body":"La moneda confirmada es el ryō. El planteamiento incluye misiones remuneradas, profesiones, comercio, negocios, contratos, impuestos, alquileres y propiedades.\n\nEntre los negocios previstos hay restaurantes, armas y equipo, ropa, herbolarios, talleres, servicios médicos y comercios generales. Sus reglas concretas y valores siguen pendientes.","example":"","questions":["¿Qué actividades necesitan diseñarse primero?","¿Qué riesgos de equilibrio debería estudiar el equipo?"],"type":"defined","reference":false,"source":"ECONOMÍA (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"legacy-36","category":"Economía"},{"id":37,"categoryId":11,"title":"Negocios de jugadores","summary":"Los negocios tendrán inventario, precios, propietarios y transacciones.","body":"Estos cuatro elementos forman parte del planteamiento confirmado. No se han definido precios, límites, interfaces ni procedimientos de compraventa.","example":"","questions":["¿Qué información necesita un propietario?","¿Qué operaciones deberían quedar registradas?"],"type":"defined","reference":false,"source":"ECONOMÍA (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"legacy-37","category":"Economía"},{"id":38,"categoryId":11,"title":"Alquileres con margen","summary":"Los avisos y periodos de gracia evitan pérdidas por ausencias breves.","body":"El sistema de alquileres debe avisar y conceder periodos de gracia. Nadie debería perder su vivienda por no conectarse un día.\n\nLa duración, los costes y el procedimiento de avisos no están definidos.","example":"","questions":["¿Qué margen debería proponerse?","¿Cómo gestionar ausencias prolongadas de forma justa?"],"type":"defined","reference":false,"source":"ECONOMÍA (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"legacy-38","category":"Economía"},{"id":39,"categoryId":13,"title":"Gobierno mixto","summary":"Los cargos en rol funcionan bajo supervisión del staff.","body":"Se prevén Hokage, Consejo, responsables ninja y tesorería, con supervisión fuera de personaje del staff.\n\nEl Hokage no puede saltarse las normas ni sancionar fuera de personaje. El control del dinero público se trata en su propia ficha.","example":"IC significa dentro del personaje; OOC, fuera del personaje. Son ámbitos distintos de actuación.","questions":["¿Qué responsabilidades requieren una definición más detallada?","¿Cómo mantener separados los conflictos IC y OOC?"],"type":"defined","reference":false,"source":"GOBIERNO Y ADMINISTRACIÓN (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"legacy-39","category":"Gobierno y administración"},{"id":40,"categoryId":12,"title":"Misiones automáticas","summary":"Tablones y NPC ofrecerán misiones.","body":"El planteamiento confirmado incluye misiones automáticas mediante tablones y NPC. No define aún catálogo, recompensas ni funcionamiento técnico.\n\nLos contratos entre jugadores y los eventos importantes tienen fichas separadas.","example":"","questions":["¿Qué tipos de misión debería incluir el primer catálogo?","¿Qué información debe mostrar una misión antes de aceptarla?"],"type":"defined","reference":false,"source":"GOBIERNO Y ADMINISTRACIÓN (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"legacy-40","category":"Misiones y eventos"},{"id":41,"categoryId":13,"title":"Principios de administración","summary":"Normas claras, registros y protección frente al favoritismo.","body":"La administración tendrá normativa clara, jerarquía del staff, registro de sanciones y resolución de conflictos.\n\nSe exige transparencia, protección contra favoritismos y separación entre actuaciones dentro y fuera del personaje. Los procedimientos detallados siguen pendientes.","example":"","questions":["¿Qué procedimientos deberían documentarse primero?","¿Cómo hacer comprensibles las decisiones administrativas?"],"type":"defined","reference":false,"source":"GOBIERNO Y ADMINISTRACIÓN (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"legacy-41","category":"Gobierno y administración"},{"id":42,"categoryId":9,"title":"Percepción mixta","summary":"Combina ventajas pasivas y comprobaciones activas.","body":"Ese formato mixto está confirmado. Percepción está relacionada parcialmente con Genjutsu.\n\nNo están definidos sus usos concretos, efectos, fórmulas ni comprobaciones. La detección de chakra no está aprobada y el D100 no vuelve obligatorias estas comprobaciones.","example":"","questions":["¿Qué situaciones encajan como ventajas pasivas y cuáles como comprobaciones activas?","¿Qué información falta para concretarlas?"],"type":"defined","reference":false,"source":"Estado vigente","designNote":"","key":"legacy-42","category":"Genjutsu y Percepción"},{"id":43,"categoryId":9,"title":"Detección de chakra","summary":"Todavía no se ha decidido si formará parte del sistema.","body":"El maestro mantiene esta cuestión pendiente. No se presupone que detectar chakra sea una capacidad de Percepción.\n\nNo hay alcance, condiciones, costes ni usuarios aprobados.","example":"","questions":["¿Debe existir detección de chakra?","Si se propone, ¿cómo debería relacionarse con las habilidades y el rol?"],"type":"pending","reference":false,"source":"Estado vigente","designNote":"","key":"legacy-43","category":"Genjutsu y Percepción"},{"id":44,"categoryId":9,"title":"Usos de Percepción","summary":"Emboscadas, rastros y trampas siguen por concretar.","body":"Son cuestiones de diseño abiertas, no capacidades ya concedidas. Falta definir usos, efectos, fórmulas y comprobaciones.\n\nEl formato mixto de Percepción sigue siendo la única base general confirmada.","example":"","questions":["¿Qué uso conviene diseñar primero?","¿Qué resultados debería permitir sin sustituir la habilidad del jugador?"],"type":"pending","reference":false,"source":"Estado vigente","designNote":"","key":"legacy-44","category":"Genjutsu y Percepción"},{"id":45,"categoryId":2,"title":"Recuperación y espera previa","summary":"Vincular Recuperación al tiempo antes de regenerar.","body":"Se propone que Recuperación determine la espera previa a la regeneración. Su definición general como tiempo de recuperación está confirmada, pero esta interpretación concreta todavía no.","example":"","questions":["¿Qué relación entre el atributo y la espera sería comprensible?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-45","category":"Estadísticas"},{"id":46,"categoryId":7,"title":"Reinicio de espera al usar jutsus","summary":"Añadir el uso de técnicas como causa de reinicio.","body":"Se propone reiniciar la espera para regenerar chakra cuando se usa un jutsu. La regla confirmada solo menciona pasar un tiempo sin ser golpeado.","example":"","questions":["¿Cómo afectaría al ritmo del combate y a la viabilidad del ninjutsu?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-46","category":"Combate"},{"id":47,"categoryId":7,"title":"Exposición al canalizar chakra","summary":"Limitar acciones y permitir interrupciones durante la canalización.","body":"La propuesta plantea que, mientras se canaliza, no se pueda atacar ni lanzar técnicas y que recibir un golpe interrumpa el proceso. Ninguna de esas condiciones está confirmada.","example":"","questions":["¿Qué riesgo debería asumir quien canaliza?","¿Qué alternativas conviene comparar?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-47","category":"Combate"},{"id":48,"categoryId":7,"title":"Cantidad de chakra regenerada","summary":"Relacionar la recuperación activa con Regeneración de Chakra.","body":"El atributo describe de forma general la cantidad regenerada. Está pendiente confirmar cómo se aplicaría específicamente a la recuperación activa en combate. No se fija ninguna fórmula.","example":"","questions":["¿Cómo trasladar el atributo a la canalización activa sin crear diferencias excesivas?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-48","category":"Combate"},{"id":49,"categoryId":6,"title":"Yin y Yang en técnicas avanzadas","summary":"Usar ambas estadísticas como requisito de jutsus de rango alto.","body":"La combinación de Yin y Yang como requisito de jutsus altos es una propuesta sin confirmar. No debe confundirse con el requisito de Yin ya confirmado para genjutsu avanzado.","example":"","questions":["¿Qué técnicas justificarían ambos requisitos?","¿Conviene evaluarlo caso por caso?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-49","category":"Jutsus"},{"id":50,"categoryId":9,"title":"Reparto frente a las ilusiones","summary":"Distribuir detectar, lanzar y deshacer entre distintos atributos.","body":"Se propone que Percepción ayude a detectar ilusiones y Genjutsu a lanzarlas y deshacerlas, con Control de Chakra como apoyo. El vínculo parcial Percepción–Genjutsu sí está confirmado; este reparto concreto no.","example":"","questions":["¿Qué papel debería cumplir cada atributo?","¿Cómo explicar la diferencia entre detectar y resistir?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-50","category":"Genjutsu y Percepción"},{"id":51,"categoryId":6,"title":"Requisitos propios de cada jutsu","summary":"Definir requisitos específicos con una tabla base orientativa.","body":"Los requisitos de estadísticas forman parte de la ficha confirmada. Sigue como propuesta que cada técnica tenga requisitos propios apoyados en una tabla base por defecto, frente a mínimos fijos por rango.","example":"","questions":["¿Qué aporta cada enfoque al aprendizaje y al equilibrio?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-51","category":"Jutsus"},{"id":52,"categoryId":7,"title":"Registro de katanas","summary":"Documentar las armas escasas y su recorrido.","body":"Se propone registrar cuántas katanas existen, quién las posee y qué ocurre si se pierden o roban. El acceso limitado mediante rol está confirmado; el registro no.","example":"","questions":["¿Qué debería conservar el registro?","¿Cómo tratar una pérdida o robo sin decidirlo aún como regla?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-52","category":"Combate"},{"id":53,"categoryId":5,"title":"NPC instructores de naturaleza","summary":"Ofrecer maestros NPC para evitar bloqueos de aprendizaje.","body":"Se propone disponer de instructores NPC de cada naturaleza. El requisito de maestro para una segunda naturaleza está confirmado; esta solución adicional no.","example":"","questions":["¿Cuándo haría falta un instructor NPC?","¿Cómo conservar el valor de los maestros jugadores?"],"type":"proposal","reference":false,"source":"Propuestas aún sin confirmar","designNote":"","key":"legacy-53","category":"Afinidades de chakra"},{"id":54,"categoryId":10,"title":"D100 narrativo voluntario","summary":"Los dados apoyan el rol cuando los participantes quieren usarlos.","body":"El D100 es opcional. No sustituye saltar, esquivar, combatir, lanzar jutsus, desplazarse o entrenar mediante las mecánicas del videojuego.\n\nLas tiradas individuales son libres. Si afectan a otro personaje, requieren consentimiento de los participantes. Si alguien no quiere dados se respeta; ante un conflicto que impida continuar puede pedirse mediación administrativa, sin imponerlos.","example":"","questions":["¿Cómo explicar el consentimiento en una escena?","¿Qué ejemplos ayudarían a distinguir rol narrativo y acciones normales?"],"type":"defined","reference":false,"source":"Sistema narrativo D100 / 1. Filosofía del D100","designNote":"","key":"legacy-54","category":"Rol narrativo"},{"id":55,"categoryId":10,"title":"Guía de comandos de dados","summary":"Referencia de /roll y /rollatributo.","body":"/roll lanza un dado sin modificador de atributo. Por defecto es un D100 y admite de 2 a 1000 caras, un dado por comando, sin expresiones como 3d6.\n\n/rollatributo \u003catributo> usa D100 y añade el atributo dividido entre 5, redondeado al entero más cercano; los medios se redondean hacia arriba. Si hay dos atributos, se hacen dos tiradas independientes. No se usa combinación 70/30.\n\nCada comando dispone de su ficha para debatirlo por separado.","example":"","questions":["¿La diferencia entre comandos resulta clara?"],"type":"defined","reference":true,"source":"Sistema narrativo D100 / 2. Comandos de dados","designNote":"","key":"legacy-55","category":"Rol narrativo"},{"id":56,"categoryId":10,"title":"Resultados en proximidad","summary":"Las tiradas se muestran solo en el chat de proximidad.","body":"Se usa el mismo alcance que el chat de rol, sin fijar aquí una distancia numérica.\n\nLas tiradas de atributo muestran nombre del personaje, acción o atributo, resultado natural, modificador y resultado final. No es obligatorio indicar automáticamente éxito o fracaso.","example":"","questions":["¿Cómo presentar los datos de una tirada con claridad?"],"type":"defined","reference":false,"source":"Sistema narrativo D100 / 3. Visualización","designNote":"","key":"legacy-56","category":"Rol narrativo"},{"id":57,"categoryId":10,"title":"Resultados naturales del D100","summary":"El 1 y el 100 naturales tienen significado especial.","body":"El dado obtiene entre 1 y 100. Un 1 natural representa fallo crítico; un 100 natural, éxito extraordinario, sin ignorar requisitos especiales.\n\nEl resultado final puede superar 100 gracias a modificadores. Los atributos tienen una influencia moderada: un personaje menos experimentado puede ganar con una buena tirada.\n\nLa comparación entre personajes y los empates se tratan en fichas independientes.","example":"","questions":["¿Qué ejemplos ayudarían a interpretar los resultados extraordinarios sin ignorar requisitos especiales?"],"type":"defined","reference":false,"source":"Sistema narrativo D100 / 4. Reglas narrativas D100","designNote":"","key":"legacy-57","category":"Rol narrativo"},{"id":58,"categoryId":10,"title":"Dificultades narrativas","summary":"Referencias para resolver tiradas voluntarias.","body":"Muy fácil: 15.\nFácil: 30.\nNormal: 50.\nDifícil: 70.\nMuy difícil: 90.\nExtrema: 110.\nExtraordinaria: 125.\n\nSon referencias para el rol voluntario, nunca requisitos obligatorios para acciones normales del videojuego. Los ajustes por circunstancias tienen una ficha separada.","example":"","questions":["¿Cómo ayudar a elegir una dificultad de común acuerdo?"],"type":"defined","reference":false,"source":"Sistema narrativo D100 / 5. Dificultades narrativas de referencia","designNote":"","key":"legacy-58","category":"Rol narrativo"},{"id":59,"categoryId":10,"title":"Intentos excepcionales de técnicas","summary":"Intentar una técnica no dominada no equivale a aprenderla.","body":"El personaje debe cumplir los requisitos mínimos de estadísticas y contar con una justificación narrativa coherente. Cada jutsu definirá costes, consecuencias y si necesita autorización administrativa para el intento.\n\nLos intentos habituales pueden acordarse entre participantes. Un intento excepcional no enseña permanentemente el jutsu ni elimina requisitos especiales. El registro administrativo tiene su propia ficha.","example":"","questions":["¿Qué información debe tener una ficha para que un intento excepcional se entienda?"],"type":"defined","reference":false,"source":"Sistema narrativo D100 / 6. Técnicas excepcionales","designNote":"","key":"legacy-59","category":"Rol narrativo"},{"id":60,"categoryId":10,"title":"Moderación de tiradas","summary":"No hay espera ni avisos automáticos por frecuencia.","body":"/roll y /rollatributo no tienen cooldown. La propuesta de una espera de dos segundos queda descartada.\n\nNo habrá avisos automáticos por tirar demasiado rápido. Si hay abuso, un administrador podrá advertir por chat y aplicar las normas habituales.","example":"","questions":["¿Cómo explicar al jugador el uso responsable de comandos libres?"],"type":"defined","reference":false,"source":"Sistema narrativo D100 / 7. Moderación","designNote":"","key":"legacy-60","category":"Rol narrativo"},{"id":61,"categoryId":10,"title":"Notas de coherencia del maestro","summary":"Contexto documental e historial de acuerdos.","body":"- Se revisó el maestro anterior: no contenía una sección D100 ni las reglas antiguas de combinación 70/30 o cooldown de 2 segundos. Se incorporan las decisiones actuales y se descartan expresamente esas alternativas, sin afirmar que se hayan eliminado textos inexistentes.\n- El combate híbrido, el entrenamiento, los requisitos y el aprendizaje de jutsus conservan sus decisiones previas. Los intentos excepcionales no conceden aprendizaje permanente ni eximen de los requisitos mínimos o especiales.\n- Los registros administrativos automáticos de acciones excepcionales son una decisión de diseño pendiente de implementación, no una capacidad técnica verificada. No autorizan avisos automáticos por frecuencia de tiradas.\n- No se fija aquí un alcance numérico del chat, una lista de alias de atributos, validaciones de comandos ni costes concretos de jutsus: no han sido definidos en esta solicitud.\n\nEsta nota deja de ser votable. Las aportaciones históricas permanecen asociadas a su identificador original.","example":"","questions":["Si detectas una contradicción, descríbela sin tratarla como una nueva decisión."],"type":"defined","reference":true,"source":"Sistema narrativo D100 / Revisión de coherencia y límites del acuerdo","designNote":"","key":"legacy-61","category":"Rol narrativo"},{"id":62,"categoryId":6,"title":"Catálogo inicial de jutsus","summary":"Faltan ejemplos de técnicas con su ficha completa.","body":"No se han definido nombres, costes, efectos ni valores de los primeros jutsus. La estructura de la ficha y las vías generales de aprendizaje sí están confirmadas.","example":"","questions":["¿Qué técnicas convendría proponer primero?"],"type":"pending","reference":false,"source":"Pendiente de diseñar","designNote":"","key":"legacy-62","category":"Jutsus"},{"id":63,"categoryId":7,"title":"Controles de combate","summary":"El funcionamiento final necesita diseño y verificación técnica.","body":"No se han cerrado los controles ni el funcionamiento final. Primero deberán comprobarse las capacidades necesarias en la documentación oficial de nanos world. Esta web no verifica ni implementa esas capacidades.","example":"","questions":["¿Qué acciones y controles hay que verificar primero?"],"type":"pending","reference":false,"source":"Pendiente de diseñar","designNote":"","key":"legacy-63","category":"Combate"},{"id":64,"categoryId":11,"title":"Reglas económicas","summary":"El planteamiento existe; faltan las reglas concretas.","body":"Ryō, negocios, comercio y alquileres forman parte de la base confirmada. Sus valores, procedimientos y equilibrio todavía no están definidos.","example":"","questions":["¿Qué parte de la economía necesita una primera propuesta detallada?"],"type":"pending","reference":false,"source":"Pendiente de diseñar","designNote":"","key":"legacy-64","category":"Economía"},{"id":65,"categoryId":13,"title":"Procedimientos de gobierno y staff","summary":"Falta desarrollar los procedimientos del marco confirmado.","body":"El gobierno mixto, la supervisión y los principios de administración están confirmados. Sus competencias detalladas y procedimientos siguen abiertos.","example":"","questions":["¿Qué procedimiento debería diseñarse primero?"],"type":"pending","reference":false,"source":"Pendiente de diseñar","designNote":"","key":"legacy-65","category":"Gobierno y administración"},{"id":66,"categoryId":2,"title":"Valores de equilibrio","summary":"No hay números definitivos para el avance del personaje.","body":"Siguen pendientes las bonificaciones de clan, los límites por rango y la experiencia por actividad. Los ejemplos ilustrativos no sustituyen esos acuerdos.","example":"","questions":["¿Qué valores se deberían estudiar y con qué pruebas?"],"type":"pending","reference":false,"source":"Pendiente de diseñar","designNote":"","key":"legacy-66","category":"Estadísticas"},{"id":67,"categoryId":2,"title":"Constitución y vida máxima","summary":"Constitución determina la vida máxima.","body":"Constitución determina la vida máxima.\n\nNo se han definido fórmulas ni valores de vida por punto de Constitución.","example":"","questions":["¿Qué relación convendría probar?"],"type":"defined","reference":false,"source":"Desglose de ESTADÍSTICAS (confirmado)","designNote":"","key":"atributo-vida","category":"Estadísticas"},{"id":68,"categoryId":2,"title":"Espíritu y chakra máximo","summary":"Espíritu determina el chakra máximo.","body":"Espíritu determina el chakra máximo.\n\nNo se ha definido una fórmula para convertir Espíritu en cantidad de chakra.","example":"","questions":["¿Cómo debería reflejarse la reserva del personaje?"],"type":"defined","reference":false,"source":"Desglose de ESTADÍSTICAS (confirmado)","designNote":"","key":"atributo-chakra","category":"Estadísticas"},{"id":69,"categoryId":2,"title":"Recuperación y regeneración","summary":"Tiempo y cantidad son conceptos distintos.","body":"Tiempo y cantidad son conceptos distintos.\n\nRecuperación describe el tiempo que se tarda en recuperarse. Regeneración de Vida y de Chakra describen la cantidad regenerada. Convertir Recuperación específicamente en espera previa sigue siendo propuesta.","example":"","questions":["¿Qué aclaraciones ayudan a distinguir ambos conceptos?"],"type":"defined","reference":false,"source":"Desglose de ESTADÍSTICAS (confirmado)","designNote":"","key":"atributo-recuperacion","category":"Estadísticas"},{"id":70,"categoryId":2,"title":"Poder y variedad del Ninjutsu","summary":"Ninjutsu representa poder y variedad de técnicas de chakra.","body":"Ninjutsu representa poder y variedad de técnicas de chakra.\n\nNo hay fórmulas numéricas aprobadas. Sus efectos concretos tendrán que explicarse en las técnicas.","example":"","questions":["¿Qué efectos convendría estudiar por técnica?"],"type":"defined","reference":false,"source":"Desglose de ESTADÍSTICAS (confirmado)","designNote":"","key":"atributo-ninjutsu","category":"Estadísticas"},{"id":71,"categoryId":2,"title":"Eficiencia del Control de Chakra","summary":"Control de Chakra representa eficiencia y precisión.","body":"Control de Chakra representa eficiencia y precisión.\n\nIncluye menor gasto de chakra y tareas finas. No se han fijado porcentajes de ahorro ni precisión numérica.","example":"","questions":["¿Qué tareas permitirían mostrar su valor?"],"type":"defined","reference":false,"source":"Desglose de ESTADÍSTICAS (confirmado)","designNote":"","key":"atributo-control","category":"Estadísticas"},{"id":72,"categoryId":2,"title":"Yin y Yang","summary":"Son estadísticas independientes con funciones distintas.","body":"Son estadísticas independientes con funciones distintas.\n\nYin corresponde a energía espiritual e imaginación; Yang, a energía física y vitalidad. Ninguna puede ser afinidad principal. Su requisito combinado en jutsus altos sigue siendo propuesta.","example":"","questions":["¿Qué ejemplos ayudarían a entenderlas sin añadir efectos no definidos?"],"type":"defined","reference":false,"source":"Desglose de ESTADÍSTICAS (confirmado)","designNote":"","key":"atributo-yinyang","category":"Estadísticas"},{"id":73,"categoryId":9,"title":"Lanzar y resistir genjutsu","summary":"Genjutsu interviene al lanzar y resistir ilusiones.","body":"Yin es requisito de las ilusiones avanzadas. Percepción se relaciona parcialmente con Genjutsu.\n\nEl reparto concreto entre detectar, lanzar y deshacer, con Control de Chakra como apoyo, sigue siendo propuesta.","example":"","questions":["¿Qué situaciones necesitan aclaraciones antes de concretar fórmulas?"],"type":"defined","reference":false,"source":"Desglose de ESTADÍSTICAS (confirmado)","designNote":"","key":"genjutsu-base","category":"Genjutsu y Percepción"},{"id":74,"categoryId":7,"title":"Estilo Taijutsu","summary":"Combate cercano y rápido.","body":"Combate cercano y rápido.\n\nNo consume chakra y tiene poco alcance.","example":"","questions":["¿Qué pruebas permitirían evaluar estas ventajas y límites?"],"type":"defined","reference":false,"source":"Desglose de COMBATE (confirmado)","designNote":"","key":"estilo-taijutsu","category":"Combate"},{"id":75,"categoryId":7,"title":"Estilo Bukijutsu","summary":"Distancia y precisión con límites de recursos o daño.","body":"Distancia y precisión con límites de recursos o daño.\n\nEl maestro lo describe con poca munición o daño; falta concretar ese reparto sin escoger uno por cuenta propia.","example":"","questions":["¿Qué pruebas permitirían evaluar estas ventajas y límites?"],"type":"defined","reference":false,"source":"Desglose de COMBATE (confirmado)","designNote":"","key":"estilo-bukijutsu","category":"Combate"},{"id":76,"categoryId":7,"title":"Estilo Ninjutsu","summary":"Mayor daño y variedad a cambio de costes y exposición.","body":"Mayor daño y variedad a cambio de costes y exposición.\n\nGasta chakra, tiene tiempo de lanzamiento y es interrumpible.","example":"","questions":["¿Qué pruebas permitirían evaluar estas ventajas y límites?"],"type":"defined","reference":false,"source":"Desglose de COMBATE (confirmado)","designNote":"","key":"estilo-ninjutsu","category":"Combate"},{"id":77,"categoryId":7,"title":"Kunais y límites de armamento","summary":"No se contemplan armas pesadas.","body":"El maestro establece que, si se usa arma, se usen kunais. Las katanas son una excepción reservada a personas contadas por rol. No se añaden aquí otros tipos de arma.","example":"","questions":["¿Cómo explicar la excepción de las katanas con claridad?"],"type":"defined","reference":false,"source":"Desglose de COMBATE (confirmado)","designNote":"","key":"armas-base","category":"Combate"},{"id":78,"categoryId":13,"title":"Control del dinero público","summary":"El gobierno debe rendir cuentas del uso de fondos.","body":"El Hokage no puede usar fondos públicos sin control. Se requieren registros y transparencia. No se define aún un procedimiento contable.","example":"","questions":["¿Qué información debe registrarse y quién debe poder consultarla?"],"type":"defined","reference":false,"source":"Desglose de GOBIERNO Y ADMINISTRACIÓN (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"fondos-publicos","category":"Gobierno y administración"},{"id":79,"categoryId":12,"title":"Contratos entre jugadores","summary":"El planteamiento incluye encargos acordados entre personajes.","body":"Los contratos entre jugadores están confirmados como parte del sistema de misiones. No se han fijado requisitos, recompensas, garantías ni procedimiento.","example":"","questions":["¿Qué información debería contener un contrato?"],"type":"defined","reference":false,"source":"Desglose de GOBIERNO Y ADMINISTRACIÓN (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"contratos","category":"Misiones y eventos"},{"id":80,"categoryId":12,"title":"Eventos dirigidos por el staff","summary":"El staff organizará los eventos importantes.","body":"Es parte del planteamiento confirmado. No hay calendario, frecuencia ni reglas detalladas aprobadas.","example":"","questions":["¿Qué papel deberían tener estos eventos en el desarrollo del mundo?"],"type":"defined","reference":false,"source":"Desglose de GOBIERNO Y ADMINISTRACIÓN (confirmado en el planteamiento inicial, sin detallar)","designNote":"","key":"eventos","category":"Misiones y eventos"},{"id":81,"categoryId":10,"title":"Dado libre con /roll","summary":"Un solo dado, sin modificadores de atributos.","body":"Por defecto lanza un D100. Se puede elegir un dado de 2 a 1000 caras. Cada comando lanza solo un dado y no admite expresiones como 3d6.","example":"Ejemplos confirmados: /roll, /roll 6, /roll 20 y /roll 1000.","questions":["¿Los ejemplos bastan para explicar el comando?"],"type":"defined","reference":false,"source":"Desglose de Sistema narrativo D100 / 2. Comandos de dados","designNote":"","key":"roll","category":"Rol narrativo"},{"id":82,"categoryId":10,"title":"Tirada con /rollatributo","summary":"Un D100 con un modificador moderado del atributo.","body":"El modificador es el atributo dividido entre 5, redondeado al entero más cercano, con los medios hacia arriba.\n\nSi una acción requiere dos atributos se hacen dos tiradas independientes. Se descarta la combinación 70/30.","example":"Ejemplo ilustrativo con la fórmula confirmada: atributo 47 → 47 / 5 = 9,4 → modificador +9. No fija un atributo inicial.","questions":["¿Cómo explicar el cálculo a quien nunca ha usado dados?"],"type":"defined","reference":false,"source":"Desglose de Sistema narrativo D100 / 2. Comandos de dados","designNote":"","key":"rollatributo","category":"Rol narrativo"},{"id":83,"categoryId":10,"title":"Tiradas enfrentadas","summary":"Se comparan los resultados finales de los personajes.","body":"Se permiten tiradas individuales y enfrentadas. En una enfrentada gana el resultado final más alto, salvo las reglas especiales de resultados naturales.\n\nSi ambos sacan 1 natural o ambos 100 natural, se repite. Los empates finales tienen una regla propia.","example":"","questions":["¿Qué ejemplos ayudarían a aplicar las reglas de resultados naturales?"],"type":"defined","reference":false,"source":"Desglose de Sistema narrativo D100 / 4. Reglas narrativas D100","designNote":"","key":"enfrentadas","category":"Rol narrativo"},{"id":84,"categoryId":10,"title":"Empates narrativos","summary":"El atributo relevante decide el empate final.","body":"Si los resultados finales empatan, gana quien tenga el atributo relevante más alto. Si también empatan en atributo, se repite la tirada.\n\nCuando ambos obtienen 1 natural o ambos 100 natural se repite, conforme a la regla especial.","example":"","questions":["¿Cómo mostrar el motivo del desempate sin recargar el chat?"],"type":"defined","reference":false,"source":"Desglose de Sistema narrativo D100 / 4. Reglas narrativas D100","designNote":"","key":"empates","category":"Rol narrativo"},{"id":85,"categoryId":10,"title":"Ajustes por circunstancias","summary":"El contexto puede modificar la dificultad de una escena.","body":"Se permiten ajustes de ±5, ±10 o ±20. Solo se acumulan efectos diferentes y hasta un total máximo de ±30.\n\nSe pueden ajustar por acuerdo entre participantes. En enfrentadas cada personaje tiene sus propias circunstancias.","example":"","questions":["¿Qué ejemplos permitirían distinguir efectos diferentes de un mismo efecto repetido?"],"type":"defined","reference":false,"source":"Desglose de Sistema narrativo D100 / 5. Dificultades narrativas de referencia","designNote":"","key":"circunstancias","category":"Rol narrativo"},{"id":86,"categoryId":10,"title":"Registro de intentos excepcionales","summary":"Las acciones excepcionales tendrán historial administrativo.","body":"Todas las acciones excepcionales quedarán registradas automáticamente. Solo los administradores podrán consultar ese historial.\n\nLos participantes seguirán viendo las tiradas correspondientes en proximidad. Es una decisión de diseño, no una capacidad técnica ya verificada.","example":"","questions":["¿Qué información sería útil para revisar un intento sin invadir la conversación de rol?"],"type":"defined","reference":false,"source":"Desglose de Sistema narrativo D100 / 6. Técnicas excepcionales","designNote":"","key":"registro-excepcional","category":"Rol narrativo"},{"id":87,"categoryId":8,"title":"Despertar del Sharingan","summary":"El primer tomoe requiere desarrollo, emoción significativa y validación.","body":"Los personajes Uchiha comienzan sin Sharingan.\n\nPara despertar el primer tomoe se requiere progreso del personaje, un acontecimiento emocional significativo dentro del rol y validación administrativa.\n\nLas pruebas de rol y la solicitud se tramitan mediante Discord. No se han fijado niveles, plazos ni valores adicionales.","example":"","questions":["¿Cómo presentar de forma clara las pruebas de progreso y el acontecimiento de rol?"],"type":"defined","reference":false,"source":"Diseño previo del Sharingan aportado por el usuario — fase 3","designNote":"Definida en el diseño previo; aportada por el usuario en fase 3. Pendiente de revisión por el equipo. Aún no incorporada al documento maestro.","key":"sharingan-despertar","category":"Dōjutsus"},{"id":88,"categoryId":8,"title":"Evolución de los tomoes","summary":"La evolución combina progreso del personaje, un acontecimiento narrativo y aprobación.","body":"Cada evolución requiere progreso del personaje y un acontecimiento narrativo importante. No es obligatorio que cada acontecimiento sea más extremo que el anterior.\n\nLa evolución no está disponible hasta que la administración la valide.\n\nPuede producirse durante un enfrentamiento si se cumplen los requisitos y existe aprobación administrativa en ese momento. La evolución desbloqueada es permanente.","example":"","questions":["¿Cómo documentar una evolución durante un enfrentamiento sin interrumpir la escena?"],"type":"defined","reference":false,"source":"Diseño previo del Sharingan aportado por el usuario — fase 3","designNote":"Definida en el diseño previo; aportada por el usuario en fase 3. Pendiente de revisión por el equipo. Aún no incorporada al documento maestro.","key":"sharingan-tomoes","category":"Dōjutsus"},{"id":89,"categoryId":8,"title":"Activación y consumo del Sharingan","summary":"Consume chakra mientras está activo y utiliza los tomoes máximos desbloqueados.","body":"El Sharingan consume chakra mientras permanece activo. El consumo aumenta conforme evoluciona.\n\nEl personaje utiliza automáticamente el máximo número de tomoes que haya desbloqueado. Puede desactivarlo voluntariamente y se desactiva si no dispone de chakra suficiente.\n\nNo se han definido costes numéricos ni fórmulas de consumo.","example":"","questions":["¿Cómo comunicar el estado activo y la falta de chakra?","¿Qué valores convendría probar sin darlos todavía por aprobados?"],"type":"defined","reference":false,"source":"Diseño previo del Sharingan aportado por el usuario — fase 3","designNote":"Definida en el diseño previo; aportada por el usuario en fase 3. Pendiente de revisión por el equipo. Aún no incorporada al documento maestro.","key":"sharingan-consumo","category":"Dōjutsus"},{"id":90,"categoryId":8,"title":"Capacidades del Sharingan","summary":"Las ventajas progresan con los tomoes, sin inmunidad absoluta al genjutsu.","body":"Las ventajas del Sharingan progresan con sus tomoes. Incluyen mejoras relacionadas con el reconocimiento y la resistencia frente al Genjutsu.\n\nNo otorga inmunidad absoluta. No se añaden otras capacidades ni se fijan aquí magnitudes o fórmulas.","example":"","questions":["¿Cómo explicar el reconocimiento y la resistencia sin interpretarlos como inmunidad?"],"type":"defined","reference":false,"source":"Diseño previo del Sharingan aportado por el usuario — fase 3","designNote":"Definida en el diseño previo; aportada por el usuario en fase 3. Pendiente de revisión por el equipo. Aún no incorporada al documento maestro.","key":"sharingan-capacidades","category":"Dōjutsus"},{"id":91,"categoryId":8,"title":"Requisitos narrativos del Sharingan","summary":"Los acontecimientos deben justificarse mediante pruebas de rol.","body":"El despertar requiere un acontecimiento emocional significativo; cada evolución, un acontecimiento narrativo importante y progreso del personaje.\n\nLos acontecimientos deben justificarse mediante pruebas de rol. No se exige una escalada obligatoria de sucesos cada vez más extremos.\n\nLas solicitudes se gestionan en Discord y la evolución requiere validación administrativa.","example":"","questions":["¿Qué presentación de las pruebas facilitaría una revisión comprensible y consistente?"],"type":"defined","reference":false,"source":"Diseño previo del Sharingan aportado por el usuario — fase 3","designNote":"Definida en el diseño previo; aportada por el usuario en fase 3. Pendiente de revisión por el equipo. Aún no incorporada al documento maestro.","key":"sharingan-narrativa","category":"Dōjutsus"},{"id":92,"categoryId":8,"title":"Validación del Sharingan","summary":"La administración valida las solicitudes y habilita la evolución.","body":"Las solicitudes se gestionan mediante Discord y deben acompañarse de pruebas de rol que justifiquen los acontecimientos.\n\nLa evolución no está disponible hasta que la administración la valide. Durante un enfrentamiento puede evolucionar si se cumplen los requisitos y existe aprobación administrativa en ese momento. Lo desbloqueado es permanente.\n\nEsta ficha describe el diseño del juego; no implementa un trámite ni un bot de Discord.","example":"","questions":["¿Cómo debería comunicarse y quedar documentada la validación?"],"type":"defined","reference":false,"source":"Diseño previo del Sharingan aportado por el usuario — fase 3","designNote":"Definida en el diseño previo; aportada por el usuario en fase 3. Pendiente de revisión por el equipo. Aún no incorporada al documento maestro.","key":"sharingan-validacion","category":"Dōjutsus"},{"id":93,"categoryId":8,"title":"Funcionamiento del Byakugan","summary":"Sus capacidades y condiciones concretas siguen sin definirse.","body":"Solo está confirmado como habilidad de clan, no como estadística. No hay alcance, costes, requisitos ni condiciones de activación documentados.","example":"","questions":["¿Qué aspectos conviene separar cuando exista una primera propuesta?"],"type":"pending","reference":false,"source":"Desglose de CLANES (confirmado)","designNote":"","key":"byakugan","category":"Dōjutsus"}];
